def h(p):
    m = hashlib.sha256()
    with open(p, 'rb') as f:
        for c in iter(lambda: f.read(1 << 20), b''): m.update(c)
    return m.hexdigest()
def archive(src):
    rel = os.path.relpath(src, HOME); dst = os.path.join(ARCH, rel)
    if APPLY:
        os.makedirs(os.path.dirname(dst), exist_ok=True); shutil.move(src, dst)
def all_suffixed():
    for dp, dn, fn in os.walk(HOME):
        if any(x in dp for x in ('/.git', '/node_modules', '_windows-import-archive', 'Library/', '/DEV/')) and '/.claude/' not in dp:
            if '/.git' in dp or 'node_modules' in dp or '_windows-import-archive' in dp: continue
        for f in fn:
            if f.endswith(SUF): yield os.path.join(dp, f)
files = [p for p in all_suffixed() if p.startswith(os.path.join(HOME, 'DEV')) or p.startswith(os.path.join(HOME, '.claude')) or p.startswith(os.path.join(HOME, 'SecondBrain'))]
for wp in files:
    mp = wp[:-len(SUF)]; rel = os.path.relpath(wp, HOME)
    in_mem = '/memory/' in wp and '/.claude/projects/' in wp
    if in_mem:
        if not os.path.lexists(mp):
            stats['memory_restored'] += 1
            if APPLY: os.rename(wp, mp)
        else:
            stats['memory_archived'] += 1; archive(wp)
    elif '/global-memory/transcripts/' in wp or wp.endswith('/transcripts/.errors.log.from-windows'):
        stats['log_merged'] += 1
        if APPLY and os.path.lexists(mp) and not os.path.islink(mp):
            with open(mp, 'a') as out:
                out.write('\n\n# ---- imported from Windows copy (' + os.path.basename(wp) + ') ----\n')
                out.write(open(wp, 'r', errors='replace').read())
            archive(wp)
        elif APPLY and not os.path.lexists(mp):
            os.rename(wp, mp)
    elif '/global-memory/handoffs/' in wp:
        if not os.path.lexists(mp):
            stats['handoff_renamed'] += 1
            if APPLY: os.rename(wp, mp)
        else:
            stats['handoff_renamed'] += 1
            base, ext = os.path.splitext(mp)
            if APPLY: os.rename(wp, base + '.windows' + ext)
    else:
        stats['other_archived'] += 1; archive(wp)
# Fix memory index lines that point at .from-windows files
import glob
for idx in glob.glob(os.path.join(HOME, '.claude', 'projects', '*', 'memory', 'MEMORY.md')):
    d = os.path.dirname(idx)
    lines = open(idx).read().split('\n'); out = []; seen = set()
    for ln in lines:
        if 'from-windows' in ln:
            if ln.strip().startswith('- [MEMORY.md]') or 'MEMORY.md.from-windows' in ln:
                stats['index_lines_dropped'] += 1; continue
            fixed = ln.replace(SUF, '')
            import re
            target = re.search(r'\]\(([^)]+)\)', fixed)
            if target and os.path.exists(os.path.join(d, target.group(1))):
                ln = fixed; stats['index_lines_fixed'] += 1
            else:
                stats['index_lines_dropped'] += 1; continue
        if ln in seen and ln.strip(): continue
        seen.add(ln); out.append(ln)
    if APPLY and '\n'.join(out) != '\n'.join(lines):
        open(idx, 'w').write('\n'.join(out))
print(('APPLIED ' if APPLY else 'DRY RUN ') + str(stats))
EOF
